const ELWYNN_STORY = {
  key: 'ef_eagan', classicId: 5261, source: 'https://classicdb.ch/?quest=5261',
  translation: 'working-ru',
  offer: 'Иган Шкуродер ищет того, кто поохотится для него на волков. Это хорошая новость: в последнее время в Североземской долине их становится всё больше. Если тебе интересно, поговори с Иганом. Он сбоку от аббатства, слева.',
  completion: 'Верно. Я ищу того, кто поохотится для меня на волков! Ты возьмёшься?'
};
function elwynnStoryDialog(name, text, label, action) {
  if (document.getElementById('elwynn-story-dialog')) return;
  const hero = S.hero, d = document.createElement('dialog');
  d.id = 'elwynn-story-dialog';
  d.style.cssText = 'max-width:min(560px,90vw);max-height:85vh;overflow:auto;background:var(--panel);color:var(--ink);padding:20px';
  const title = document.createElement('h2'), body = document.createElement('p');
  title.id = 'elwynn-story-title'; title.textContent = name;
  d.setAttribute('aria-labelledby', title.id);
  body.textContent = text; body.style.whiteSpace = 'pre-wrap';
  const yes = document.createElement('button'), close = document.createElement('button');
  yes.type = close.type = 'button'; yes.className = close.className = 'btn';
  yes.textContent = label; close.textContent = 'Закрыть';
  yes.onclick = function () {
    if (yes.disabled || S.hero !== hero) return;
    yes.disabled = true; d.close(); action();
  };
  close.onclick = function () { d.close(); };
  d.addEventListener('close', function () { d.remove(); }, {once:true});
  d.append(title, body, yes, close); document.body.append(d); d.showModal();
}
function elwynnStoryQuest() { return QUESTS.find(function(q) { return q.k === ELWYNN_STORY.key; }); }
function elwynnStoryAvailable(q) {
  return !!q && !!S.hero && !S.walk && !S.amb && qNeedMet(q);
}
function goTake(k) {
  if (k !== ELWYNN_STORY.key) return legacyElwynnGoTake(k);
  const q = elwynnStoryQuest(), hero = S.hero;
  if (!elwynnStoryAvailable(q) || qState(k) !== 0) return;
  travel(q.t, function () {
    if (S.hero !== hero || !elwynnStoryAvailable(q) || qState(k) !== 0) return;
    elwynnStoryDialog(q.npc, ELWYNN_STORY.offer, 'Принять', function () {
      if (S.hero !== hero || S.hero.at !== q.t || !elwynnStoryAvailable(q) || qState(k) !== 0) return;
      setQ(k, 1); S.qsel = k; S.qopen = true; renderMap();
    });
  });
}
function elwynnStoryFinish(k) {
  const q = elwynnStoryQuest(), hero = S.hero;
  if (!elwynnStoryAvailable(q) || hero.at !== (q.e || q.d) || ![1,2].includes(qState(k))) return;
  elwynnStoryDialog('Иган Шкуродер', ELWYNN_STORY.completion, 'Завершить задание', function () {
    if (S.hero !== hero || !elwynnStoryAvailable(q) || hero.at !== (q.e || q.d) || ![1,2].includes(qState(k))) return;
    if (qState(k) === 1) setQ(k, 2);
    turnIn(k);
  });
}
function goTurn(k) {
  if (k !== ELWYNN_STORY.key) return legacyElwynnGoTurn(k);
  const q = elwynnStoryQuest(), hero = S.hero;
  if (!elwynnStoryAvailable(q) || qState(k) !== 2) return;
  travel(q.e || q.d, function () { if (S.hero === hero) elwynnStoryFinish(k); });
}
function goDo(k) {
  if (k !== ELWYNN_STORY.key) return legacyElwynnGoDo(k);
  const q = elwynnStoryQuest(), hero = S.hero;
  if (!elwynnStoryAvailable(q) || qState(k) !== 1) return;
  travel(q.d, function () { if (S.hero === hero) elwynnStoryFinish(k); });
}
function legacyElwynnGoDo(k) {

